// Simplified model of runc init's last steps (not runc's real code)
func finalizeAndExec(cfg Config) error {
    joinNamespaces(cfg)       // mount, pid, net, ... now apply
    pivotRoot(cfg.Rootfs)     // "/" is the container's filesystem
    // before 1.1.12: a host directory handle opened earlier is still open
    if err := chdir(cfg.Cwd); err != nil {
        return err
    }

    // fix 1: is the working directory really inside the container?
    if _, err := os.Getwd(); errors.Is(err, unix.ENOENT) {
        return errors.New("cwd is outside the container")
    }

    // fix 2: no inherited descriptor except stdin, stdout, stderr
    closeRangeCloexec(3)
    return execve(cfg.Args[0], cfg.Args, cfg.Env)
}
